use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use anyhow::{Context, Result, bail};
use sha2::{Digest, Sha256};

use super::super::source_lines;

pub(super) const REPORT_GENERATOR: &str = "redlinedb-bench sqlite_parity report";
pub(super) const REPORT_REGEN_COMMAND: &str = "just sqlite-parity-report-update";

pub(super) fn generated_comment_header(prefix: &str, source: &str, command: &str) -> String {
    format!(
        "{prefix} Generated by: {REPORT_GENERATOR}\n{prefix} Source: {source}\n{prefix} Command: {command}\n{prefix} DO NOT EDIT BY HAND.\n",
    )
}

pub(super) fn generated_xml_header(source: &str, command: &str) -> String {
    format!(
        "<!-- Generated by: {REPORT_GENERATOR} -->\n<!-- Source: {source} -->\n<!-- Command: {command} -->\n<!-- DO NOT EDIT BY HAND. -->\n",
    )
}

pub(super) fn repo_root_from_readme(readme: &Path) -> PathBuf {
    readme
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
        .to_path_buf()
}

pub(super) fn tex_int(value: usize) -> String {
    comma_int(value).replace(',', "{,}")
}

pub(super) fn consume_line_endings(text: &str, index: usize) -> usize {
    let mut cursor = index;
    while cursor < text.len() {
        if text[cursor..].starts_with("\r\n") {
            cursor += 2;
        } else if text[cursor..].starts_with('\n') || text[cursor..].starts_with('\r') {
            cursor += 1;
        } else {
            break;
        }
    }
    cursor
}

pub(super) fn source_lines_csv(summary: &source_lines::SourceLineSummary) -> String {
    let mut out = generated_comment_header(
        "#",
        "crates/{redlinedb,sql,kernel,ffi}/src",
        REPORT_REGEN_COMMAND,
    );
    out.push_str("component,loc,ksloc,files,source_path,notes\n");
    for component in &summary.components {
        out.push_str(&format!(
            "{},{},{:.1},{},{},{}\n",
            component.id,
            component.lines,
            source_lines::ksloc(component.lines),
            component.files,
            csv(&component.path),
            csv(&component.notes)
        ));
    }
    out.push_str(&format!(
        "redlinedb_core_total,{},{:.1},{},{},{}\n",
        summary.total_lines,
        summary.redlinedb_ksloc(),
        summary.total_files,
        csv("crates/{redlinedb,sql,kernel,ffi}/src"),
        csv("production Rust source; excludes tests, benches, examples, cfg(test) items, blank lines, and comments")
    ));
    out.push_str(&format!(
        "sqlite_reference,{},{:.1},,fixed,{}\n",
        summary.sqlite_reference_lines,
        summary.sqlite_reference_ksloc(),
        csv("fixed SQLite source-line reference")
    ));
    out
}

pub(super) fn comma_int(value: usize) -> String {
    let digits = value.to_string();
    let mut out = String::new();
    for (index, ch) in digits.chars().enumerate() {
        if index > 0 && (digits.len() - index) % 3 == 0 {
            out.push(',');
        }
        out.push(ch);
    }
    out
}

pub(super) fn check_files(writes: &[(PathBuf, String)]) -> Result<()> {
    let mut drifted = Vec::new();
    for (path, contents) in writes {
        let current = fs::read_to_string(path).unwrap_or_default();
        if current != *contents {
            drifted.push(path.display().to_string());
        }
    }
    if !drifted.is_empty() {
        bail!("sqlite parity report drift: {}", drifted.join(", "));
    }
    Ok(())
}

pub(super) fn write_files(writes: &[(PathBuf, String)]) -> Result<()> {
    for (path, contents) in writes {
        if let Some(parent) = path.parent()
            && !parent.as_os_str().is_empty()
        {
            fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
        }
        fs::write(path, contents).with_context(|| format!("write {}", path.display()))?;
    }
    Ok(())
}

pub(super) fn color(value: f64) -> &'static str {
    if value < -5.0 {
        "#dc2626"
    } else if value < -0.5 {
        "#f97316"
    } else if value <= 0.5 {
        "#6b7280"
    } else if value <= 5.0 {
        "#16a34a"
    } else {
        "#2563eb"
    }
}

pub(super) fn improvement_cell(value: f64) -> String {
    format!(
        r#"<span style="color:{}">{:.2}%</span>"#,
        color(value),
        value
    )
}

pub(super) fn csv(value: &str) -> String {
    if value.contains([',', '"', '\n']) {
        format!("\"{}\"", value.replace('"', "\"\""))
    } else {
        value.to_owned()
    }
}

pub(super) fn escape_md(value: &str) -> String {
    value.replace('|', "\\|")
}

pub(super) fn display_path(path: &Path) -> std::borrow::Cow<'_, str> {
    path.to_string_lossy()
}

pub(super) fn expected_case_id_text(ids: &BTreeSet<String>) -> String {
    let mut out = ids.iter().cloned().collect::<Vec<_>>().join("\n");
    out.push('\n');
    out
}

pub(super) fn sha256_file(path: &Path) -> Result<String> {
    let bytes = fs::read(path).with_context(|| format!("hash {}", path.display()))?;
    Ok(sha256_hex(&bytes))
}

pub(super) fn sha256_hex(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

pub(super) fn git_sha() -> String {
    resolve_git_sha(env_git_sha(), git_head_sha)
}

pub(super) fn resolve_git_sha(
    env_sha: Option<String>,
    git_fallback: impl FnOnce() -> String,
) -> String {
    env_sha.unwrap_or_else(git_fallback)
}

pub(super) fn git_head_sha() -> String {
    Command::new("git")
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .and_then(|output| {
            if output.status.success() {
                Some(String::from_utf8_lossy(&output.stdout).trim().to_owned())
            } else {
                None
            }
        })
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "<unknown>".to_owned())
}

pub(super) fn env_git_sha() -> Option<String> {
    normalize_git_sha(std::env::var("REDLINEDB_BENCH_GIT_SHA").ok())
}

pub(super) fn normalize_git_sha(value: Option<String>) -> Option<String> {
    value
        .map(|candidate| candidate.trim().to_owned())
        .filter(|candidate| !candidate.is_empty())
}

pub(super) fn existing_manifest_git_sha(path: &Path) -> Result<Option<String>> {
    if !path.exists() {
        return Ok(None);
    }
    let manifest = fs::read_to_string(path)
        .with_context(|| format!("read existing manifest {}", path.display()))?;
    let value: serde_json::Value = serde_json::from_str(&manifest)
        .with_context(|| format!("parse existing manifest {}", path.display()))?;
    Ok(value
        .get("git_sha")
        .and_then(|git_sha| git_sha.as_str())
        .map(str::to_owned)
        .and_then(|git_sha| normalize_git_sha(Some(git_sha))))
}

pub(super) fn normalized_command(command: &[String]) -> Vec<String> {
    command
        .iter()
        .filter(|arg| arg.as_str() != "--check")
        .cloned()
        .collect()
}
